Voici un exemple de code en C utilisant la bibliothèque SDL2 pour implémenter le jeu du serpent :

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#include "SDL2/SDL.h"

// Largeur et hauteur de la fenêtre
#define LARGEUR 800
#define HAUTEUR 600

// Taille d'une case du serpent ou d'une pomme
#define CASE_SIZE 20

// Nombre maximal de pommes
#define NB_MAX_POMMES 5

// Définition des couleurs en SDL_Color
typedef struct {
    Uint8 r, g, b, a;
} Color;

// Structure représentant le serpent
typedef struct {
    int x, y; // Position du serpent en pixels
    int dirX, dirY; // Direction du serpent (en pixels)
    int longueur; // Longueur du serpent en nombre de cases
    SDL_Rect cases[SNAKE_MAX_SIZE]; // Cases du serpent
} Snake;

// Structure représentant une pomme
typedef struct {
    int x, y; // Position de la pomme en pixels
} Apple;

// Structure représentant un mur
typedef struct {
    SDL_Rect rect; // Rectangle représentant le mur
} Wall;

// Structure représentant les paramètres du jeu
typedef struct {
    Snake serpent;
    Apple pommes[NB_MAX_POMMES];
    Wall murs[NB_MAX_MURS];
    int score;
    int pommesRestantes;
    int difficulty;
} GameParams;

// Fonction pour initialiser les structures de jeu
GameParams* initGameParams(int difficulty);

// Fonction pour dessiner un serpent à partir de sa structure
void drawSnake(SDL_Renderer* renderer, Snake* serpent);

// Fonction pour placer une pomme à une position valide
void placeApple(GameParams* params);

// Fonction principale de boucle de jeu
int runGameLoop(SDL_Window* window, SDL_Renderer* renderer, GameParams* params);

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        SDL_WINDOWPOS_CENTERED_DISPLAY(0),
        LARGEUR, HAUTEUR,
        SDL_WINDOW_SHOWN
    );

    SDL_CreateRenderer(
        SDL_GetWindowFromID(SDL_GetWindowID(window)),
        -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC
    );

    srand(time(NULL));
    GameParams* params = initGameParams(1);

    int running = 1;
    while (running) {
        running = runGameLoop(SDL_GetRendererRenderer(), SDL_GetRenderer(), params);
    }

    SDL_DestroyRenderer(SDL_GetRenderer());
    SDL_DestroyWindow(SDL_GetWindowFromID(SDL_GetWindowID(window)));

    SDL_Quit();

    return 0;
}
```

Le code ci-dessus est un exemple simplifié, mais il vous donne une idée de la structure d'un programme implémentant le jeu du serpent en C avec SDL2.

